func accountSourceIcon(source string) string {
	source = strings.ToLower(source)
	if strings.Contains(source, "android") || strings.Contains(source, "iphone") || strings.Contains(source, "ipad") || strings.Contains(source, "ios") || strings.Contains(source, "app store") {
		return "Smartphone"
	}
	if strings.Contains(source, "web") {
		return "Language"
	}
	return ""
}

func accountDate(value string) string {
	if date, err := time.Parse(time.RFC3339, value); err == nil {
		return date.Format("Jan 2, 2006")
	}
	return value
}

func accountVerificationLabel(p PageProps, value string) string {
	switch value {
	case "individual":
		return L(p, "feed_account_verification_blue", "Blue")
	case "business", "organization":
		return L(p, "feed_account_verification_business", "Business")
	case "government":
		return L(p, "feed_account_verification_government", "Government")
	default:
		return value
	}
}

